import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
H=W=30
def maximal_rects(T,minh=1,minw=1):
    best=set()
    heights=[0]*W
    for i in range(H):
        heights=[heights[j]+1 if T[i][j]==8 else 0 for j in range(W)]
        st=[]
        heights2=heights+[0]
        for j in range(W+1):
            cur=heights2[j]; start=j
            while st and st[-1][1]>=cur:
                s,hh=st.pop()
                if hh>=minh and j-s>=minw: best.add((i-hh+1,s,hh,j-s))
                start=s
            st.append((start,cur))
    def contained(a,b): return a[0]>=b[0] and a[1]>=b[1] and a[0]+a[2]<=b[0]+b[2] and a[1]+a[3]<=b[1]+b[3]
    return sorted(r for r in best if not any(contained(r,o) and o!=r for o in best))

for name in ['Demo pair 1','Demo pair 2']:
