        for j in range(W):
            if T[i][j]!=8: continue
            wmax=0
            while j+wmax<W and T[i][j+wmax]==8: wmax+=1
            for w in range(minw,wmax+1):
                h=0
                while i+h<H and all(T[i+h][j+x]==8 for x in range(w)): h+=1
                for hh in range(minh,h+1):
                    out.append((i,j,hh,w))
    return out
