def transform(grid):
    H=len(grid); W=len(grid[0])
    out=[row[:] for row in grid]
    def uniform_rects(T,minh,minw):
        res=[]
        for i in range(H):
            for j in range(W):
                c=T[i][j]; wmax=0
                while j+wmax<W and T[i][j+wmax]==c: wmax+=1
                for w in range(minw,wmax+1):
                    h=0
                    while i+h<H and all(T[i+h][j+x]==c for x in range(w)): h+=1
                    for hh in range(minh,h+1):
                        res.append((i,j,hh,w))
        return res
    mark=[[False]*W for _ in range(H)]
    # efficient: for each cell, find max uniform rect extents; instead use brute but bounded
    rects=uniform_rects(grid,5,5)
    for (i,j,h,w) in rects:
        for y in range(i,i+h):
            for x in range(j,j+w):
                mark[y][x]=True
    for y in range(H):
        for x in range(W):
            if mark[y][x]: out[y][x]=4
    return out

